// Generate discriminating tuples for FLOAT vs DOUBLE (and FMA / dbl-sub) blend arithmetic.
use std::io::Write;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
        self.0 = x; x
    }
    fn u32(&mut self) -> u32 { (self.next() >> 32) as u32 }
    fn f01(&mut self) -> f32 { // full-mantissa uniform [0,1)
        (self.u32() >> 8) as f32 / (1u32 << 24) as f32
    }
}

// ---- %g with precision 6, matching printf/ostream default ----
fn g6(v: f32) -> String {
    if v.is_nan() { return if v.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if v.is_infinite() { return if v < 0.0 { "-inf".into() } else { "inf".into() }; }
    if v == 0.0 { return if v.is_sign_negative() { "-0".into() } else { "0".into() }; }
    let s = format!("{:.5e}", v);            // e.g. "-1.23456e6"
    let (mant, exp) = s.split_once('e').unwrap();
    let x: i32 = exp.parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect(); // 6 digits
    let sign = if neg { "-" } else { "" };
    if x < -4 || x >= 6 {
        let mut frac = digits[1..].trim_end_matches('0').to_string();
        if !frac.is_empty() { frac.insert(0, '.'); }
        let es = if x < 0 { '-' } else { '+' };
        format!("{}{}{}{}e{}{:02}", sign, &digits[0..1], frac, "", es, x.abs())
    } else if x >= 0 {
        let ip = &digits[..(x as usize + 1)];
        let frac = digits[(x as usize + 1)..].trim_end_matches('0');
        if frac.is_empty() { format!("{}{}", sign, ip) } else { format!("{}{}.{}", sign, ip, frac) }
    } else {
        let zeros = "0".repeat((-x - 1) as usize);
        let frac = format!("{}{}", zeros, digits);
        let frac = frac.trim_end_matches('0');
        if frac.is_empty() { format!("{}0", sign) } else { format!("{}0.{}", sign, frac) }
    }
}

// candidates
fn c_float(c1: f32, c2: f32, t: f32) -> f32 { c1 * (1.0f32 - t) + c2 * t }
fn c_double(c1: f32, c2: f32, t: f32) -> f32 {
    ((c1 as f64) * (1.0f64 - t as f64) + (c2 as f64) * (t as f64)) as f32
}
fn c_fma_a(c1: f32, c2: f32, t: f32) -> f32 { c1.mul_add(1.0f32 - t, c2 * t) }
fn c_fma_b(c1: f32, c2: f32, t: f32) -> f32 { c2.mul_add(t, c1 * (1.0f32 - t)) }
fn c_dblsub(c1: f32, c2: f32, t: f32) -> f32 { // 1.0-t in double, narrowed, rest float
    let s = (1.0f64 - t as f64) as f32; c1 * s + c2 * t
}
fn c_lerp(c1: f32, c2: f32, t: f32) -> f32 { c1 + (c2 - c1) * t }

// stof-safe: shortest-roundtrip decimal that strtof reproduces, and not subnormal (F12)
fn ok_arg(v: f32) -> bool { v.is_finite() && (v == 0.0 || v.abs() >= f32::MIN_POSITIVE) }
fn arg(v: f32) -> String { let s = format!("{}", v); s }

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let seed: u64 = args.get(1).map(|s| s.parse().unwrap()).unwrap_or(12345);
    let iters: u64 = args.get(2).map(|s| s.parse().unwrap()).unwrap_or(2_000_000);
    let mut r = Rng(seed | 1);
    let out = std::io::stdout();
    let mut w = std::io::BufWriter::new(out.lock());

    let mut n_bitdiff = 0u64; let mut n_strdiff = 0u64;
    for _ in 0..iters {
        // pick a generation mode
        let mode = r.u32() % 6;
        let mut vals = [0f32; 5];
        let t: f32;
        match mode {
            0 => { for v in vals.iter_mut() { *v = r.f01(); } t = r.f01(); }
            1 => { // scaled, many mantissa bits, moderate exponents
                for v in vals.iter_mut() { let e = (r.u32() % 60) as i32 - 30; *v = r.f01() * 2f32.powi(e); }
                t = r.f01();
            }
            2 => { // wide exponents
                for v in vals.iter_mut() { let e = (r.u32() % 200) as i32 - 100; *v = r.f01() * 2f32.powi(e); }
                let e = (r.u32() % 40) as i32 - 20; t = r.f01() * 2f32.powi(e);
            }
            3 => { // t near 0 or near 1 (adversarial for 1-t)
                for v in vals.iter_mut() { *v = r.f01(); }
                let base = if r.u32() % 2 == 0 { 0.0f32 } else { 1.0f32 };
                let d = r.f01() * 2f32.powi(-(r.u32() % 25) as i32);
                t = base + if base == 0.0 { d } else { -d };
            }
            4 => { // t possibly outside [0,1], signs mixed
                for v in vals.iter_mut() { let s = if r.u32()%2==0 {1.0} else {-1.0}; *v = s * r.f01() * 2f32.powi((r.u32()%20) as i32 - 10); }
                let s = if r.u32()%2==0 {1.0f32} else {-1.0}; t = s * r.f01() * 4.0;
            }
            _ => { // near-tie hunting: nudge results toward 6-digit boundaries
                for v in vals.iter_mut() { *v = r.f01() * 2f32.powi((r.u32()%14) as i32); }
                t = r.f01();
            }
        }
        let (r1,g1,b1,r2,g2) = (vals[0],vals[1],vals[2],vals[3],vals[4]);
        if !ok_arg(r1)||!ok_arg(g1)||!ok_arg(b1)||!ok_arg(r2)||!ok_arg(g2)||!ok_arg(t) { continue; }
        let b2 = 0.1f32; // F1: always default

        let ch = [(r1,r2),(g1,g2),(b1,b2)];
        let f: Vec<f32> = ch.iter().map(|&(a,b)| c_float(a,b,t)).collect();
        let d: Vec<f32> = ch.iter().map(|&(a,b)| c_double(a,b,t)).collect();
        let bits_differ = f.iter().zip(&d).any(|(a,b)| a.to_bits() != b.to_bits());
        if !bits_differ { continue; }
        n_bitdiff += 1;
        let fs = format!("{} {} {}", g6(f[0]), g6(f[1]), g6(f[2]));
        let ds = format!("{} {} {}", g6(d[0]), g6(d[1]), g6(d[2]));
        let fa: Vec<f32> = ch.iter().map(|&(a,b)| c_fma_a(a,b,t)).collect();
        let fb: Vec<f32> = ch.iter().map(|&(a,b)| c_fma_b(a,b,t)).collect();
        let dsu: Vec<f32> = ch.iter().map(|&(a,b)| c_dblsub(a,b,t)).collect();
        let lp: Vec<f32> = ch.iter().map(|&(a,b)| c_lerp(a,b,t)).collect();
        let fas = format!("{} {} {}", g6(fa[0]), g6(fa[1]), g6(fa[2]));
        let fbs = format!("{} {} {}", g6(fb[0]), g6(fb[1]), g6(fb[2]));
        let dsus = format!("{} {} {}", g6(dsu[0]), g6(dsu[1]), g6(dsu[2]));
        let lps = format!("{} {} {}", g6(lp[0]), g6(lp[1]), g6(lp[2]));
        let strdiff = fs != ds;
        if strdiff { n_strdiff += 1; }
        // TAB-separated record
        writeln!(w, "{}\t{} {} {} {} {} {}\t{}\t{}\t{}\t{}\t{}\t{}",
            if strdiff {"STRDIFF"} else {"bitonly"},
            arg(r1),arg(g1),arg(b1),arg(r2),arg(g2),arg(t),
            fs, ds, fas, fbs, dsus, lps).unwrap();
        if n_strdiff >= 400 && n_bitdiff >= 1200 { break; }
    }
    eprintln!("bitdiff={} strdiff={}", n_bitdiff, n_strdiff);
}
