fn main(){
    // Exhaustive over ALL 2^32 f32 bit patterns: is (1.0f32 - t) == ((1.0f64 - t as f64) as f32) ?
    let mut diff = 0u64; let mut ex: Vec<u32> = vec![];
    for bits in 0u32..=u32::MAX {
        let t = f32::from_bits(bits);
        if !t.is_finite() { continue; }
        let a = 1.0f32 - t;
        let b = (1.0f64 - t as f64) as f32;
        if a.to_bits() != b.to_bits() { diff += 1; if ex.len() < 8 { ex.push(bits); } }
        if bits == u32::MAX { break; }
    }
    println!("differing t values: {}  examples: {:?}", diff, ex);
}
