// Reference implementation of blend + %g, replicating x86 SSE operand-order NaN semantics.
const DEFAULT_QNAN: u32 = 0xFFC0_0000; // x86 "QNaN floating-point indefinite" = negative

fn quiet(x: f32) -> f32 { f32::from_bits(x.to_bits() | 0x0040_0000) }

/// x86 `SUBSS dest, src`  (dest = a)
fn sub_x86(a: f32, b: f32) -> f32 {
    if a.is_nan() { return quiet(a); }
    if b.is_nan() { return quiet(b); }
    let r = a - b;
    if r.is_nan() { f32::from_bits(DEFAULT_QNAN) } else { r }
}
/// x86 `MULSS dest, src`  (dest = a)
fn mul_x86(a: f32, b: f32) -> f32 {
    if a.is_nan() { return quiet(a); }
    if b.is_nan() { return quiet(b); }
    let r = a * b;
    if r.is_nan() { f32::from_bits(DEFAULT_QNAN) } else { r }
}
/// x86 `ADDSS dest, src`  (dest = a)
fn add_x86(a: f32, b: f32) -> f32 {
    if a.is_nan() { return quiet(a); }
    if b.is_nan() { return quiet(b); }
    let r = a + b;
    if r.is_nan() { f32::from_bits(DEFAULT_QNAN) } else { r }
}

/// blend(rgb1, rgb2, t) exactly as compiled at 0x403530.
fn blend(c1: (f32,f32,f32), c2: (f32,f32,f32), t: f32) -> (f32,f32,f32) {
    // b channel first (as emitted); dest of the final ADDSS is the c1 term
    let sb = sub_x86(1.0, t); let bb = add_x86(mul_x86(c1.2, sb), mul_x86(c2.2, t));
    let sg = sub_x86(1.0, t); let gg = add_x86(mul_x86(c1.1, sg), mul_x86(c2.1, t));
    // r channel: dest of the final ADDSS is the c2 term (operands swapped!)
    let sr = sub_x86(1.0, t); let rr = add_x86(mul_x86(c2.0, t), mul_x86(c1.0, sr));
    (rr, gg, bb)
}

fn g6(v: f32) -> String {
    if v.is_nan() { return if v.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if v.is_infinite() { return if v < 0.0 { "-inf".into() } else { "inf".into() }; }
    if v == 0.0 { return if v.is_sign_negative() { "-0".into() } else { "0".into() }; }
    let s = format!("{:.5e}", v);
    let (mant, exp) = s.split_once('e').unwrap();
    let x: i32 = exp.parse().unwrap();
    let sign = if mant.starts_with('-') { "-" } else { "" };
    let d: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    if x < -4 || x >= 6 {
        let f = d[1..].trim_end_matches('0');
        let dot = if f.is_empty() { String::new() } else { format!(".{}", f) };
        format!("{}{}{}e{}{:02}", sign, &d[0..1], dot, if x<0 {'-'} else {'+'}, x.abs())
    } else if x >= 0 {
        let k = x as usize + 1;
        let f = d[k..].trim_end_matches('0');
        if f.is_empty() { format!("{}{}", sign, &d[..k]) } else { format!("{}{}.{}", sign, &d[..k], f) }
    } else {
        let f = format!("{}{}", "0".repeat((-x-1) as usize), d);
        let f = f.trim_end_matches('0');
        if f.is_empty() { format!("{}0", sign) } else { format!("{}0.{}", sign, f) }
    }
}

fn main(){
    let a: Vec<String> = std::env::args().skip(1).collect();
    // args: r1 g1 b1 r2 g2 ratio   (b2 always 0.1 per F1)
    let p = |i: usize| -> f32 { a[i].parse::<f32>().unwrap_or_else(|_| {
        // handle inf/nan spellings like strtof
        let s = a[i].to_ascii_lowercase();
        if s.contains("-nan") { -f32::NAN } else if s.contains("nan") { f32::NAN }
        else if s.starts_with('-') { f32::NEG_INFINITY } else { f32::INFINITY } }) };
    let (c1, c2, t) = ((p(0),p(1),p(2)), (p(3),p(4),0.1f32), p(5));
    let o = blend(c1, c2, t);
    println!("{} {} {}", g6(o.0), g6(o.1), g6(o.2));
}
